#include <stdint.h>
#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

/* Diagnostic only: no VM and no product code. Volatile keeps the repeated
   local read and accumulation observable to the C optimizer. */
int main(int argc, char **argv) {
    if (argc != 3 || strcmp(argv[1], "-e") != 0) return 2;
    char *end = NULL;
    errno = 0;
    uint64_t n = strtoull(argv[2], &end, 10);
    if (errno != 0 || *end != '\0' || n == 0 || n > UINT64_MAX / 7) return 2;
    puts("BENCH-READY");
    if (fflush(stdout) != 0 || getchar() == EOF) return 3;
    volatile uint64_t local = 7;
    volatile uint64_t result = 0;
    for (uint64_t i = 0; i < n; ++i) result = result + local;
    printf("BENCH-DONE %" PRIu64 "\n", (uint64_t)result);
    if (fflush(stdout) != 0 || getchar() == EOF) return 3;
    return 0;
}

