etw_resources.capture-admin.ps1:
[CmdletBinding(SupportsShouldProcess = $true)]
param([string]$PythonExecutable)

$ErrorActionPreference = 'Stop'
$projectRoot = (Resolve-Path -LiteralPath (Join-Path $PSScriptRoot '..\..\..')).Path
$driver = Join-Path $PSScriptRoot 'capture-admin.py'
$environment = Get-Content -LiteralPath (Join-Path $PSScriptRoot 'python-environment.json') -Raw | ConvertFrom-Json
$python = if ($PythonExecutable) { $PythonExecutable } else { $environment.executable }
if (-not (Test-Path -LiteralPath $python -PathType Leaf)) { throw "Python executable not found: $python" }
if (-not (Test-Path -LiteralPath $driver -PathType Leaf)) { throw "Missing driver: $driver" }

if ((Get-FileHash -LiteralPath $driver -Algorithm SHA256).Hash.ToLowerInvariant() -ne $environment.driver_sha256) { throw 'Driver changed; review and refresh metadata first' }

Write-Output "Project: $projectRoot"
Write-Output "Python: $python"
Write-Output 'Records one uniquely named scheduler session with 3 baseline Sigma and 3 native control runs.'
Write-Output 'Checks existing WPR state first; writes a fresh admin-* folder; never stops other sessions.'
if ($PSCmdlet.ShouldProcess($projectRoot, 'Capture owned WPR scheduler diagnostic')) {
    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = [Security.Principal.WindowsPrincipal]::new($identity)
    if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
        throw 'Open an administrator PowerShell window and run this script. No elevation is attempted automatically.'
    }
    Push-Location -LiteralPath $projectRoot
    try {
        & $python -E -P -X utf8 $driver
        if ($LASTEXITCODE -ne 0) { throw "Capture driver failed: $LASTEXITCODE" }
        Write-Output 'Inspect the new admin-*/capture.json for status and trace location.'
    }
    finally { Pop-Location }
}

